SOURCE_CLAIM_JSON: {"title":"2022 National Medical Security Development Statistical Bulletin","publisher":"National Healthcare Security Administration","publication_date":"2023-07-10","url":"https://www.nhsa.gov.cn/art/2023/7/10/art_7_10995.html","claim":"At the end of 2022, China had 1,345.92 million basic medical-insurance enrollees and coverage remained stable above 95%.","locator":"lines 10-14","source_type":"official","source_confidence":"high","source_confidence_reason":"Primary sector bulletin with explicit enrollment and coverage figures, though still an official report.","final_evidence_use":"final_evidence","period_fit":"Retrospective 2022 official bulletin published in 2023.","ruler_attribution":"Attributable to the Xi-era health system and party-state policy apparatus, not Xi alone.","contrary_evidence":["Coverage says little about care quality or affordability.","Official reporting may smooth over local access barriers."],"lenses":["6B.2","6B.4","6B.10"]}

